        /**
         * Parse a css color value (#rgb, #rrggbb, #rrggbbaa, rgb()/rgba(); any other syntax through canvasColor) into [r, g, b].
         * @param {string} v - Computed custom property value.
         * @returns {number[]|null} Components, or null if not parsable.
         */
